import {getLanguage} from './i18n.js';
import {graphicsSettings} from './graphics-settings.js';
export function createGraphicsControls(root,{getState,getScene}){root.setAttribute('data-i18n-skip','');let language;const tr=(it,en)=>getLanguage()==='en'?en:it;
 function render(){language=getLanguage();root.setAttribute('aria-label',tr('Grafica e prestazioni','Graphics and performance'));const s=getState(),g=graphicsSettings(s);root.innerHTML=`<h3>${tr('Grafica e prestazioni','Graphics and performance')}</h3><label class="graphics-select">${tr('Dettaglio della scena','Scene detail')}<select id="graphicsQuality"><option value="economy">${tr('Essenziale','Essential')}</option><option value="balanced">${tr('Bilanciato','Balanced')}</option><option value="detailed">${tr('Dettagliato','Detailed')}</option></select></label><p class="graphics-hint">${tr('I calcoli fisici mantengono la stessa precisione. Tutti i filetti restano visibili.','Physics calculations retain the same precision. All telltales remain visible.')}</p><div class="graphics-options"><label><input id="graphicsShadows" type="checkbox" ${g.shadows?'checked':''}>${tr('Ombre','Shadows')}</label><label><input id="graphicsStats" type="checkbox" ${s.graphicsStats?'checked':''}>${tr('Monitor prestazioni','Performance monitor')}</label></div><fieldset class="shape-line-editor" aria-label="Aspetto delle linee sulle vele"><legend>${tr('Linee di forma delle vele','Sail shape lines')}</legend>
  <label class="shape-line-switch"><input id="shapeLinesVisible" type="checkbox" ${g.shapeLinesVisible?'checked':''}>${tr('Mostra linee di forma','Show shape lines')}</label>
  <div class="shape-line-properties"><label for="shapeLineOpacity">${tr('Visibilità delle linee','Line visibility')} <output id="shapeLineOpacityOutput">${Math.round(g.shapeLineOpacity*100)}%</output></label><input id="shapeLineOpacity" type="range" min="0" max="100" step="5" value="${Math.round(g.shapeLineOpacity*100)}">
  <label class="shape-line-color">${tr('Colore delle linee','Line color')}<input id="shapeLineColor" type="color" value="${g.shapeLineColor}" aria-label="${tr('Colore delle linee di forma','Shape line color')}"></label></div>
  <div class="shape-line-additional"><label><input id="shapeSeamsVisible" type="checkbox" ${g.shapeSeamsVisible?'checked':''}>${tr('Cuciture','Seams')}</label><label><input id="shapeBattensVisible" type="checkbox" ${g.shapeBattensVisible?'checked':''}>${tr('Stecche','Battens')}</label></div>
  <p>${tr('Le impostazioni modificano soltanto l’aspetto 3D, non la forma fisica delle vele.','These settings affect only the 3D appearance, not the physical sail shape.')}</p>
</fieldset><div id="graphicsMonitor" class="graphics-monitor" ${s.graphicsStats?'':'hidden'}><span>FPS<b data-graphics-fps>—</b></span><span>${tr('CPU scena','Scene CPU')}<b data-graphics-cpu>—</b></span><span>Draw calls<b data-graphics-calls>—</b></span><span>${tr('Triangoli','Triangles')}<b data-graphics-triangles>—</b></span></div><details class="graphics-details"><summary>${tr('Cosa cambia e come scegliere','What changes and how to choose')}</summary><p>${tr('Essenziale: superfici più leggere e meno decorazioni; adatto al mobile. Bilanciato: buona leggibilità con un costo ridotto. Dettagliato: griglia originale e ombre più fini. I livelli cambiano anche mare e frequenza delle animazioni, conservando geometria fisica, filetti e contatti del vento.','Essential: lighter surfaces and fewer decorations, useful on mobile. Balanced: readable shapes at a reduced cost. Detailed: original sail grid and finer shadows. Levels also change the sea and animation rate, preserving physical geometry, telltales and wind contacts.')}</p><p>${tr('Se gli FPS sono bassi, disattiva le ombre o scegli Essenziale. Quantità dei flussi, pressioni e vettori delle forze incidono a loro volta sul costo. FPS e draw calls sono misurati sul dispositivo; “CPU scena” esclude i calcoli fisici e non misura il tempo GPU.','If FPS is low, turn off shadows or choose Essential. Wind density, pressure maps and force vectors also add work. FPS and draw calls are measured on your device; “Scene CPU” excludes physics calculations and does not measure GPU time.')}</p><a class="graphics-report-link" href="${tr('./performance/index.html','./performance/en.html')}" target="_blank" rel="noopener">${tr('Confronto dei tempi CPU ↗','CPU comparison report ↗')}</a></details>`;
 root.querySelector('#graphicsQuality').value=g.quality;
 for(const [id,event,key,read]of [['graphicsQuality','change','graphicsQuality',e=>e.value],['graphicsShadows','change','graphicsShadows',e=>e.checked],['graphicsStats','change','graphicsStats',e=>e.checked],['shapeLinesVisible','change','shapeLinesVisible',e=>e.checked],['shapeLineOpacity','input','shapeLineOpacity',e=>Number(e.value)],['shapeLineColor','input','shapeLineColor',e=>e.value],['shapeSeamsVisible','change','shapeSeamsVisible',e=>e.checked],['shapeBattensVisible','change','shapeBattensVisible',e=>e.checked]])root.querySelector('#'+id).addEventListener(event,e=>{getState()[key]=read(e.target);update();});
 }
 function update(){if(language!==getLanguage())render();const s=getState(),g=graphicsSettings(s);for(const [id,value]of [['graphicsQuality',g.quality]]){const el=root.querySelector('#'+id);if(el.value!==String(value))el.value=String(value);}for(const id of ['graphicsShadows','graphicsStats'])root.querySelector('#'+id).checked=!!s[id];for(const id of ['shapeLinesVisible','shapeSeamsVisible','shapeBattensVisible'])root.querySelector('#'+id).checked=!!s[id];root.querySelector('#shapeLineOpacity').value=String(Math.round(g.shapeLineOpacity*100));root.querySelector('#shapeLineOpacityOutput').textContent=Math.round(g.shapeLineOpacity*100)+'%';root.querySelector('#shapeLineColor').value=g.shapeLineColor;root.querySelector('.shape-line-properties').classList.toggle('disabled',!g.shapeLinesVisible);const monitor=root.querySelector('#graphicsMonitor');monitor.hidden=!s.graphicsStats;if(!s.graphicsStats||root.closest('.hidden'))return;const p=getScene()?.performanceStats?.();if(!p)return;const f=n=>Number.isFinite(n)?n.toLocaleString(language==='en'?'en-GB':'it-IT',{maximumFractionDigits:1}):'—';root.querySelector('[data-graphics-fps]').textContent=f(p.fps);root.querySelector('[data-graphics-cpu]').textContent=f(p.cpuMs)+' ms';root.querySelector('[data-graphics-calls]').textContent=f(p.calls);root.querySelector('[data-graphics-triangles]').textContent=f(p.triangles);}
 render();return{update};}
